window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7a402db46c0b56f7"]={"versions": [{"id": "FIG-7a402db46c0b56f7", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR M2-Metamodells aus <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells für anwenderspezifische bzw. generische Stützstellenachsen (<code>SwAxisGeneric</code>) innerhalb der Kalibrier- und Messdatenmodellierung (<code>SwDataDefProps</code>). Es dient der Abbildung von Kennlinien- und Kennfeld-Achsen (Curves/Maps), deren Interpolationslogik oder Speicherorganisation von standardisierten AUTOSAR-Achstypen (z. B. <code>STD_AXIS</code>, <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>RES_AXIS</code>) abweicht und proprietäre Parameter für Kalibriertools (ASAM MCD-2 MC / A2L) sowie anwendungsspezifische Interpolationsroutinen benötigt.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> (Klasse):</strong></li>\n<li>Konkrete Verwendung/Instanz einer generischen Achse an einem Kalibrierparameter oder Datenobjekt.</li>\n<li>Attribut: <code>swNumberOfAxisPoints: Integer</code> – Definiert die Anzahl der Stützstellen; annotiert mit dem Stereotyp <code>«atpVariation»</code> (unterliegt dem AUTOSAR-Variantenmanagement, z. B. bindbar zu Post-Build oder Pre-Compile).</li>\n<li><strong><code>SwGenericAxisParam</code> (Klasse):</strong></li>\n<li>Konkrete Belegung eines generischen Achsparameters.</li>\n<li>Attribut: <code>vf: Numerical</code> – Numerischer Skalarwert des Parameters; annotiert mit <code>«atpVariation»</code> (variantenabhängige Wertbelegung).</li>\n<li><strong><code>SwAxisType</code> (Klasse, spezialisiert <code>ARElement</code>):</strong></li>\n<li>Top-Level-Modellelement (<code>ARElement</code>, eigenständig paketierbar in <code>ARPackage</code>). Definiert die strukturelle Schablone (Metadaten-Typ) für eine Klasse generischer Achsen.</li>\n<li><strong><code>SwGenericAxisParamType</code> (Klasse, spezialisiert <code>Identifiable</code>):</strong></li>\n<li>Formale Parameterdefinition innerhalb eines <code>SwAxisType</code> (besitzt <code>shortName</code>, UUID etc. über Vererbung von <code>Identifiable</code>).</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> $\\rightarrow$ <code>SwAxisType</code>:</strong> Unidirektionale Referenz <code>+swAxisType</code> mit Multiplizität <code>1</code> (jede generische Achse muss genau einen Typen referenzieren).</li>\n<li><strong><code>SwAxisGeneric</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParam</code>:</strong> Komposition <code>+swGenericAxisParam</code> mit Multiplizität <code>0..*</code> (eine generische Achse kapselt beliebig viele konkrete Parameterwerte).</li>\n<li><strong><code>SwGenericAxisParam</code> $\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Unidirektionale Assoziation <code>+swGenericAxisParamType</code> mit Multiplizität <code>1</code> (jeder Parameterwert ist eindeutig typisiert).</li>\n<li><strong><code>SwAxisType</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Komposition <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..*</code> (der Achstyp deklariert die Menge gültiger Parameterdefinitionen).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Typ-Instanz-Muster (Design-Time / Modellierung):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Typdeklaration:</em> Definition eines wiederverwendbaren <code>SwAxisType</code> im Modell inklusive dessen formaler Parameter (<code>SwGenericAxisParamType</code>).</li>\n<li><em>Instanziierung:</em> Bei Deklaration einer Kennlinie/eines Kennfelds wird ein <code>SwAxisGeneric</code> zugewiesen, der auf den <code>SwAxisType</code> verweist.</li>\n<li><em>Parametrierung:</em> Für jeden geforderten <code>SwGenericAxisParamType</code> instanziiert <code>SwAxisGeneric</code> ein <code>SwGenericAxisParam</code> mit dem konkreten Wert <code>vf</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Build- & Toolchain-Abhängigkeit:</strong></li>\n<li>Keine direkte Laufzeit-Zustandsmaschine; statische Struktur dient Generatoren (RTE-Generator, A2L-Exportfilter).</li>\n<li>Evaluierung der <code>«atpVariation»</code>-Bedingungen während des System-/ECU-Extracts oder zur Post-Build-Ladephase.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>ASAM MCD-2 MC / A2L-Generierung:</strong></li>\n<li>Generische Achsen mappen im A2L-Datensatz typischerweise auf <code>AXIS_PTS</code> bzw. <code>RECORD_LAYOUT</code>-Strukturen mit erweiterten Attributen. Kalibriertools (z. B. INCA, CANape) benötigen die über <code>SwGenericAxisParam</code> definierten Metadaten, um nicht-lineare oder algorithmisch berechnete Achsenpunkte korrekt visualisieren und manipulieren zu können.</li>\n<li><strong>Codegenerierung & BSW/ASW-Einschränkungen:</strong></li>\n<li>Im Gegensatz zu Standardachsen existieren für <code>SwAxisGeneric</code> keine standardisierten AUTOSAR-Basis-Interpolationsroutinen in den Standard-Bibliotheken (BFX/IFX).</li>\n<li>Der Anwendungsentwickler muss sicherstellen, dass die zugehörige Softwarekomponente (SWC) oder proprietäre Mathematik-Bibliothek die Interpretation der Parameter (<code>vf</code>) und der variablen Stützstellenanzahl (<code>swNumberOfAxisPoints</code>) zur Laufzeit korrekt implementiert.</li>\n<li><strong>Variantenmanagement:</strong></li>\n<li>Da sowohl Achsdimension (<code>swNumberOfAxisPoints</code>) als auch Parametrierung (<code>vf</code>) variierbar sind, müssen Speicherallokation im Linker (ROM/RAM-Bedarf für Stützstellen) und Zugriffsroutinen auf maximale Dimensionen bzw. dynamische Bounds ausgelegt werden.</li>\n</ul>"}, {"id": "FIG-7f8c03f6dcbba163", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR M2-Metamodells aus <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells für anwenderspezifische bzw. generische Stützstellenachsen (<code>SwAxisGeneric</code>) innerhalb der Kalibrier- und Messdatenmodellierung (<code>SwDataDefProps</code>). Es dient der Abbildung von Kennlinien- und Kennfeld-Achsen (Curves/Maps), deren Interpolationslogik oder Speicherorganisation von standardisierten AUTOSAR-Achstypen (z. B. <code>STD_AXIS</code>, <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>RES_AXIS</code>) abweicht und proprietäre Parameter für Kalibriertools (ASAM MCD-2 MC / A2L) sowie anwendungsspezifische Interpolationsroutinen benötigt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> (Klasse):</strong></li>\n<li>Konkrete Verwendung/Instanz einer generischen Achse.</li>\n<li>Attribut: <code>swNumberOfAxisPoints: Integer [0..1]</code> – Optionale Angabe der Stützstellenanzahl; annotiert mit Stereotyp <code>«atpVariation»</code>.</li>\n<li><strong><code>SwGenericAxisParam</code> (Klasse):</strong></li>\n<li>Konkrete Belegung eines generischen Achsparameters.</li>\n<li>Attribut: <code>vf: Numerical [1..*]</code> – Liste von mindestens einem numerischen Wert; annotiert mit <code>«atpVariation»</code>.</li>\n<li><strong><code>SwAxisType</code> (Klasse, spezialisiert <code>ARElement</code>):</strong></li>\n<li>Top-Level-Modellelement (<code>ARElement</code>), definiert die strukturelle Schablone für generische Achsen.</li>\n<li><strong><code>SwGenericAxisParamType</code> (Klasse, spezialisiert <code>Identifiable</code>):</strong></li>\n<li>Formale Parameterdefinition innerhalb eines <code>SwAxisType</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> $\\rightarrow$ <code>SwAxisType</code>:</strong> Unidirektionale Referenz <code>+swAxisType</code> mit Multiplizität <code>1</code>.</li>\n<li><strong><code>SwAxisGeneric</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParam</code>:</strong> Komposition <code>+swGenericAxisParam</code> mit Multiplizität <code>0..*</code>.</li>\n<li><strong><code>SwGenericAxisParam</code> $\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Unidirektionale Assoziation <code>+swGenericAxisParamType</code> mit Multiplizität <code>1</code>.</li>\n<li><strong><code>SwAxisType</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Komposition <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Typ-Instanz-Muster (Design-Time / Modellierung):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Typdeklaration:</em> Definition eines wiederverwendbaren <code>SwAxisType</code> im Modell inklusive dessen formaler Parameter (<code>SwGenericAxisParamType</code>).</li>\n<li><em>Instanziierung:</em> Bei Deklaration einer Kennlinie/eines Kennfelds wird ein <code>SwAxisGeneric</code> zugewiesen, der auf den <code>SwAxisType</code> verweist.</li>\n<li><em>Parametrierung:</em> Für jeden geforderten <code>SwGenericAxisParamType</code> instanziiert <code>SwAxisGeneric</code> ein <code>SwGenericAxisParam</code> mit dem konkreten Wert <code>vf</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Build- & Toolchain-Abhängigkeit:</strong></li>\n<li>Keine direkte Laufzeit-Zustandsmaschine; statische Struktur dient Generatoren (RTE-Generator, A2L-Exportfilter).</li>\n<li>Evaluierung der <code>«atpVariation»</code>-Bedingungen während des System-/ECU-Extracts oder zur Post-Build-Ladephase.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>M2-Konformität:</strong> Jede Instanz von <code>SwAxisGeneric</code> muss zwingend auf genau einen <code>SwAxisType</code> verweisen (<code>+swAxisType 1</code>).</li>\n<li><strong>Multiplizitäten:</strong> Das Attribut <code>swNumberOfAxisPoints</code> ist optional (<code>[0..1]</code>), während <code>vf</code> ein Vektor aus mindestens einem numerischen Wert (<code>[1..*]</code>) ist.</li>\n<li><strong>Konsistenzregel:</strong> Jeder instanziierte <code>SwGenericAxisParam</code> muss exakt einen zugehörigen <code>SwGenericAxisParamType</code> referenzieren (<code>1</code>), der im deklarierten <code>SwAxisType</code> enthalten ist.</li>\n<li><strong>Variantenbildung:</strong> Stützstellenanzahl (<code>swNumberOfAxisPoints</code>) und Parameterwerte (<code>vf</code>) unterliegen dem Variantenmanagement (<code>«atpVariation»</code>).</li>\n</ul>"}, {"id": "FIG-97909f64548ac947", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR M2-Metamodells aus <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells für anwenderspezifische bzw. generische Stützstellenachsen (<code>SwAxisGeneric</code>) innerhalb der Kalibrier- und Messdatenmodellierung (<code>SwDataDefProps</code>). Es dient der Abbildung von Kennlinien- und Kennfeld-Achsen (Curves/Maps), deren Interpolationslogik oder Speicherorganisation von standardisierten AUTOSAR-Achstypen (z. B. <code>STD_AXIS</code>, <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>RES_AXIS</code>) abweicht und proprietäre Parameter für Kalibriertools (ASAM MCD-2 MC / A2L) sowie anwendungsspezifische Interpolationsroutinen benötigt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> (Klasse):</strong></li>\n<li>Konkrete Verwendung/Instanz einer generischen Achse (ohne eigene Attribute im Diagramm).</li>\n<li><strong><code>SwGenericAxisParam</code> (Klasse):</strong></li>\n<li>Konkrete Belegung eines generischen Achsparameters.</li>\n<li>Attribut: <code>vf: Numerical [1..*]</code> – Liste von mindestens einem numerischen Wert; annotiert mit <code>«atpVariation»</code>.</li>\n<li><strong><code>SwAxisType</code> (Klasse, spezialisiert <code>ARElement</code>):</strong></li>\n<li>Top-Level-Modellelement (<code>ARElement</code>), definiert die Schablone für generische Achsen.</li>\n<li><strong><code>SwGenericAxisParamType</code> (Klasse, spezialisiert <code>Identifiable</code>):</strong></li>\n<li>Formale Parameterdefinition innerhalb eines <code>SwAxisType</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> $\\rightarrow$ <code>SwAxisType</code>:</strong> Unidirektionale Referenz <code>+swAxisType</code> mit Multiplizität <code>1</code>.</li>\n<li><strong><code>SwAxisGeneric</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParam</code>:</strong> Komposition <code>+swGenericAxisParam</code> mit Multiplizität <code>0..*</code>.</li>\n<li><strong><code>SwGenericAxisParam</code> $\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Unidirektionale Assoziation <code>+swGenericAxisParamType</code> mit Multiplizität <code>1</code>.</li>\n<li><strong><code>SwAxisType</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Komposition <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Typ-Instanz-Muster (Design-Time / Modellierung):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Typdeklaration:</em> Definition eines wiederverwendbaren <code>SwAxisType</code> im Modell inklusive dessen formaler Parameter (<code>SwGenericAxisParamType</code>).</li>\n<li><em>Instanziierung:</em> Bei Deklaration einer Kennlinie/eines Kennfelds wird ein <code>SwAxisGeneric</code> zugewiesen, der auf den <code>SwAxisType</code> verweist.</li>\n<li><em>Parametrierung:</em> Für jeden geforderten <code>SwGenericAxisParamType</code> instanziiert <code>SwAxisGeneric</code> ein <code>SwGenericAxisParam</code> mit dem konkreten Wert <code>vf</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Build- & Toolchain-Abhängigkeit:</strong></li>\n<li>Keine direkte Laufzeit-Zustandsmaschine; statische Struktur dient Generatoren (RTE-Generator, A2L-Exportfilter).</li>\n<li>Evaluierung der <code>«atpVariation»</code>-Bedingungen während des System-/ECU-Extracts oder zur Post-Build-Ladephase.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>M2-Konformität:</strong> Jede Instanz von <code>SwAxisGeneric</code> muss zwingend auf einen <code>SwAxisType</code> verweisen (<code>+swAxisType 1</code>).</li>\n<li><strong>Parameterbelegung:</strong> Parameterwerte werden über das attributlose Element <code>SwAxisGeneric</code> aggregiert und in <code>SwGenericAxisParam</code> als Wertefolge <code>vf: Numerical [1..*]</code> abgelegt.</li>\n<li><strong>Variantenbildung:</strong> Die Wertbelegungen <code>vf</code> unterliegen dem Variantenmanagement (<code>«atpVariation»</code>).</li>\n</ul>"}, {"id": "FIG-4403f342ca4feff4", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR M2-Metamodells aus <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells für anwenderspezifische bzw. generische Stützstellenachsen (<code>SwAxisGeneric</code>) innerhalb der Kalibrier- und Messdatenmodellierung (<code>SwDataDefProps</code>). Es dient der Abbildung von Kennlinien- und Kennfeld-Achsen (Curves/Maps), deren Interpolationslogik oder Speicherorganisation von standardisierten AUTOSAR-Achstypen (z. B. <code>STD_AXIS</code>, <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>RES_AXIS</code>) abweicht und proprietäre Parameter für Kalibriertools (ASAM MCD-2 MC / A2L) sowie anwendungsspezifische Interpolationsroutinen benötigt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> (Klasse):</strong></li>\n<li>Konkrete Verwendung/Instanz einer generischen Achse.</li>\n<li><strong><code>SwGenericAxisParam</code> (Klasse):</strong></li>\n<li>Konkrete Belegung eines generischen Achsparameters.</li>\n<li>Attribut: <code>vf: Numerical [1..*] {ordered}</code> – Geordnete Sequenz von mindestens einem numerischen Wert; annotiert mit <code>«atpVariation»</code>.</li>\n<li><strong><code>SwAxisType</code> (Klasse, spezialisiert <code>ARElement</code>):</strong></li>\n<li>Top-Level-Modellelement (<code>ARElement</code>), definiert die Schablone für generische Achsen.</li>\n<li><strong><code>SwGenericAxisParamType</code> (Klasse, spezialisiert <code>Identifiable</code>):</strong></li>\n<li>Formale Parameterdefinition innerhalb eines <code>SwAxisType</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> $\\rightarrow$ <code>SwAxisType</code>:</strong> Unidirektionale Referenz <code>+swAxisType</code> mit Multiplizität <code>1</code>.</li>\n<li><strong><code>SwAxisGeneric</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParam</code>:</strong> Komposition <code>+swGenericAxisParam</code> mit Multiplizität <code>0..*</code>.</li>\n<li><strong><code>SwGenericAxisParam</code> $\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Unidirektionale Assoziation <code>+swGenericAxisParamType</code> mit Multiplizität <code>1</code>.</li>\n<li><strong><code>SwAxisType</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Komposition <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Typ-Instanz-Muster (Design-Time / Modellierung):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Typdeklaration:</em> Definition eines wiederverwendbaren <code>SwAxisType</code> im Modell inklusive dessen formaler Parameter (<code>SwGenericAxisParamType</code>).</li>\n<li><em>Instanziierung:</em> Bei Deklaration einer Kennlinie/eines Kennfelds wird ein <code>SwAxisGeneric</code> zugewiesen, der auf den <code>SwAxisType</code> verweist.</li>\n<li><em>Parametrierung:</em> Für jeden geforderten <code>SwGenericAxisParamType</code> instanziiert <code>SwAxisGeneric</code> ein <code>SwGenericAxisParam</code> mit dem konkreten Wert <code>vf</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Build- & Toolchain-Abhängigkeit:</strong></li>\n<li>Keine direkte Laufzeit-Zustandsmaschine; statische Struktur dient Generatoren (RTE-Generator, A2L-Exportfilter).</li>\n<li>Evaluierung der <code>«atpVariation»</code>-Bedingungen während des System-/ECU-Extracts oder zur Post-Build-Ladephase.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>M2-Konformität:</strong> Jede Instanz von <code>SwAxisGeneric</code> erfordert genau eine Referenz auf einen <code>SwAxisType</code> (<code>+swAxisType 1</code>).</li>\n<li><strong>Ordnungseigenschaft:</strong> Die Wertefolge <code>vf</code> in <code>SwGenericAxisParam</code> ist explizit als geordnet spezifiziert (<code>{ordered}</code>), sodass die Reihenfolge der numerischen Werte normativ erhalten bleibt.</li>\n<li><strong>Variantenbildung:</strong> Die geordneten Werte <code>vf</code> unterliegen dem Variantenmanagement (<code>«atpVariation»</code>).</li>\n</ul>"}, {"id": "FIG-3e4e3f41a2f3d6c2", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR M2-Metamodells aus <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells für anwenderspezifische bzw. generische Stützstellenachsen (<code>SwAxisGeneric</code>) innerhalb der Kalibrier- und Messdatenmodellierung (<code>SwDataDefProps</code>). Es dient der Abbildung von Kennlinien- und Kennfeld-Achsen (Curves/Maps), deren Interpolationslogik oder Speicherorganisation von standardisierten AUTOSAR-Achstypen (z. B. <code>STD_AXIS</code>, <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>RES_AXIS</code>) abweicht und proprietäre Parameter für Kalibriertools (ASAM MCD-2 MC / A2L) sowie anwendungsspezifische Interpolationsroutinen benötigt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> (Klasse):</strong></li>\n<li>Konkrete Verwendung/Instanz einer generischen Achse.</li>\n<li><strong><code>SwGenericAxisParam</code> (Klasse):</strong></li>\n<li>Konkrete Belegung eines generischen Achsparameters.</li>\n<li>Attribut: <code>vf: Numerical [1..*] {ordered}</code> – Geordnete Sequenz von mindestens einem numerischen Wert; annotiert mit <code>«atpVariation»</code>.</li>\n<li><strong><code>SwAxisType</code> (Klasse, spezialisiert <code>ARElement</code>):</strong></li>\n<li>Top-Level-Modellelement (<code>ARElement</code>), definiert die Schablone für generische Achsen.</li>\n<li><strong><code>SwGenericAxisParamType</code> (Klasse, spezialisiert <code>Identifiable</code>):</strong></li>\n<li>Formale Parameterdefinition innerhalb eines <code>SwAxisType</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> $\\rightarrow$ <code>SwAxisType</code>:</strong> Unidirektionale Referenz <code>+swAxisType</code> mit Multiplizität <code>1</code>.</li>\n<li><strong><code>SwAxisGeneric</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParam</code>:</strong> Komposition <code>+swGenericAxisParam</code> mit Multiplizität <code>0..*</code>.</li>\n<li><strong><code>SwGenericAxisParam</code> $\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Unidirektionale Assoziation <code>+swGenericAxisParamType</code> mit Multiplizität <code>1</code>.</li>\n<li><strong><code>SwAxisType</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Komposition <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Typ-Instanz-Muster (Design-Time / Modellierung):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Typdeklaration:</em> Definition eines wiederverwendbaren <code>SwAxisType</code> im Modell inklusive dessen formaler Parameter (<code>SwGenericAxisParamType</code>).</li>\n<li><em>Instanziierung:</em> Bei Deklaration einer Kennlinie/eines Kennfelds wird ein <code>SwAxisGeneric</code> zugewiesen, der auf den <code>SwAxisType</code> verweist.</li>\n<li><em>Parametrierung:</em> Für jeden geforderten <code>SwGenericAxisParamType</code> instanziiert <code>SwAxisGeneric</code> ein <code>SwGenericAxisParam</code> mit dem konkreten Wert <code>vf</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Build- & Toolchain-Abhängigkeit:</strong></li>\n<li>Keine direkte Laufzeit-Zustandsmaschine; statische Struktur dient Generatoren (RTE-Generator, A2L-Exportfilter).</li>\n<li>Evaluierung der <code>«atpVariation»</code>-Bedingungen während des System-/ECU-Extracts oder zur Post-Build-Ladephase.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>M2-Konformität:</strong> Jede Instanz von <code>SwAxisGeneric</code> erfordert genau eine Referenz auf einen <code>SwAxisType</code> (<code>+swAxisType 1</code>).</li>\n<li><strong>Ordnungseigenschaft:</strong> Die Wertefolge <code>vf</code> in <code>SwGenericAxisParam</code> ist explizit als geordnet spezifiziert (<code>{ordered}</code>), sodass die Reihenfolge der numerischen Werte normativ erhalten bleibt.</li>\n<li><strong>Variantenbildung:</strong> Die geordneten Werte <code>vf</code> unterliegen dem Variantenmanagement (<code>«atpVariation»</code>).</li>\n</ul>"}, {"id": "FIG-f5d15fe9842cd792", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR M2-Metamodells aus <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells für anwenderspezifische bzw. generische Stützstellenachsen (<code>SwAxisGeneric</code>) innerhalb der Kalibrier- und Messdatenmodellierung (<code>SwDataDefProps</code>). Es dient der Abbildung von Kennlinien- und Kennfeld-Achsen (Curves/Maps), deren Interpolationslogik oder Speicherorganisation von standardisierten AUTOSAR-Achstypen (z. B. <code>STD_AXIS</code>, <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>RES_AXIS</code>) abweicht und proprietäre Parameter für Kalibriertools (ASAM MCD-2 MC / A2L) sowie anwendungsspezifische Interpolationsroutinen benötigt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> (Klasse):</strong></li>\n<li>Konkrete Verwendung/Instanz einer generischen Achse.</li>\n<li><strong><code>SwGenericAxisParam</code> (Klasse):</strong></li>\n<li>Konkrete Belegung eines generischen Achsparameters.</li>\n<li>Attribut: <code>vf: Numerical [0..*] {ordered}</code> – Geordnete Sequenz von beliebig vielen (auch null) numerischen Werten; annotiert mit <code>«atpVariation»</code>.</li>\n<li><strong><code>SwAxisType</code> (Klasse, spezialisiert <code>ARElement</code>):</strong></li>\n<li>Top-Level-Modellelement (<code>ARElement</code>), definiert die Schablone für generische Achsen.</li>\n<li><strong><code>SwGenericAxisParamType</code> (Klasse, spezialisiert <code>Identifiable</code>):</strong></li>\n<li>Formale Parameterdefinition innerhalb eines <code>SwAxisType</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> $\\rightarrow$ <code>SwAxisType</code>:</strong> Unidirektionale Referenz <code>+swAxisType</code> mit Multiplizität <code>0..1</code> (optional).</li>\n<li><strong><code>SwAxisGeneric</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParam</code>:</strong> Komposition <code>+swGenericAxisParam</code> mit Multiplizität <code>0..*</code>.</li>\n<li><strong><code>SwGenericAxisParam</code> $\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Unidirektionale Assoziation <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..1</code> (optional).</li>\n<li><strong><code>SwAxisType</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Komposition <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Typ-Instanz-Muster (Design-Time / Modellierung):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Typdeklaration:</em> Definition eines wiederverwendbaren <code>SwAxisType</code> im Modell inklusive dessen formaler Parameter (<code>SwGenericAxisParamType</code>).</li>\n<li><em>Instanziierung:</em> Bei Deklaration einer Kennlinie/eines Kennfelds wird ein <code>SwAxisGeneric</code> zugewiesen, der auf den <code>SwAxisType</code> verweist.</li>\n<li><em>Parametrierung:</em> Für jeden geforderten <code>SwGenericAxisParamType</code> instanziiert <code>SwAxisGeneric</code> ein <code>SwGenericAxisParam</code> mit dem konkreten Wert <code>vf</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Build- & Toolchain-Abhängigkeit:</strong></li>\n<li>Keine direkte Laufzeit-Zustandsmaschine; statische Struktur dient Generatoren (RTE-Generator, A2L-Exportfilter).</li>\n<li>Evaluierung der <code>«atpVariation»</code>-Bedingungen während des System-/ECU-Extracts oder zur Post-Build-Ladephase.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Optionale Typisierung:</strong> Die Referenz <code>+swAxisType</code> von <code>SwAxisGeneric</code> ist optional (<code>0..1</code>). Ebenso ist die Typzuordnung <code>+swGenericAxisParamType</code> an <code>SwGenericAxisParam</code> optional (<code>0..1</code>).</li>\n<li><strong>Leere Wertlisten:</strong> Das Attribut <code>vf</code> in <code>SwGenericAxisParam</code> erlaubt eine leere Wertebelegung (<code>[0..*]</code>), behält jedoch die Ordnungseigenschaft (<code>{ordered}</code>).</li>\n<li><strong>Variantenbildung:</strong> Die Parameterwerte <code>vf</code> unterliegen dem Variantenmanagement (<code>«atpVariation»</code>).</li>\n</ul>"}, {"id": "FIG-95424b0e01017484", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR M2-Metamodells aus <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells für anwenderspezifische bzw. generische Stützstellenachsen (<code>SwAxisGeneric</code>) innerhalb der Kalibrier- und Messdatenmodellierung (<code>SwDataDefProps</code>). Es dient der Abbildung von Kennlinien- und Kennfeld-Achsen (Curves/Maps), deren Interpolationslogik oder Speicherorganisation von standardisierten AUTOSAR-Achstypen (z. B. <code>STD_AXIS</code>, <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>RES_AXIS</code>) abweicht und proprietäre Parameter für Kalibriertools (ASAM MCD-2 MC / A2L) sowie anwendungsspezifische Interpolationsroutinen benötigt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> (Klasse):</strong></li>\n<li>Konkrete Verwendung/Instanz einer generischen Achse.</li>\n<li><strong><code>SwGenericAxisParam</code> (Klasse):</strong></li>\n<li>Konkrete Belegung eines generischen Achsparameters.</li>\n<li>Attribut: <code>vf: Numerical [0..*] {ordered}</code> – Geordnete Sequenz von beliebig vielen (auch null) numerischen Werten; annotiert mit <code>«atpVariation»</code>.</li>\n<li><strong><code>SwAxisType</code> (Klasse, spezialisiert <code>ARElement</code>):</strong></li>\n<li>Top-Level-Modellelement (<code>ARElement</code>), definiert die Schablone für generische Achsen.</li>\n<li><strong><code>SwGenericAxisParamType</code> (Klasse, spezialisiert <code>Identifiable</code>):</strong></li>\n<li>Formale Parameterdefinition innerhalb eines <code>SwAxisType</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> $\\rightarrow$ <code>SwAxisType</code>:</strong> Unidirektionale Referenz <code>+swAxisType</code> mit Multiplizität <code>0..1</code> (optional).</li>\n<li><strong><code>SwAxisGeneric</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParam</code>:</strong> Komposition <code>+swGenericAxisParam</code> mit Multiplizität <code>0..*</code>.</li>\n<li><strong><code>SwGenericAxisParam</code> $\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Unidirektionale Assoziation <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..1</code> (optional).</li>\n<li><strong><code>SwAxisType</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Komposition <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Typ-Instanz-Muster (Design-Time / Modellierung):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Typdeklaration:</em> Definition eines wiederverwendbaren <code>SwAxisType</code> im Modell inklusive dessen formaler Parameter (<code>SwGenericAxisParamType</code>).</li>\n<li><em>Instanziierung:</em> Bei Deklaration einer Kennlinie/eines Kennfelds wird ein <code>SwAxisGeneric</code> zugewiesen, der auf den <code>SwAxisType</code> verweist.</li>\n<li><em>Parametrierung:</em> Für jeden geforderten <code>SwGenericAxisParamType</code> instanziiert <code>SwAxisGeneric</code> ein <code>SwGenericAxisParam</code> mit dem konkreten Wert <code>vf</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Build- & Toolchain-Abhängigkeit:</strong></li>\n<li>Keine direkte Laufzeit-Zustandsmaschine; statische Struktur dient Generatoren (RTE-Generator, A2L-Exportfilter).</li>\n<li>Evaluierung der <code>«atpVariation»</code>-Bedingungen während des System-/ECU-Extracts oder zur Post-Build-Ladephase.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Optionale Typisierung:</strong> Die Referenz <code>+swAxisType</code> von <code>SwAxisGeneric</code> ist optional (<code>0..1</code>). Ebenso ist die Typzuordnung <code>+swGenericAxisParamType</code> an <code>SwGenericAxisParam</code> optional (<code>0..1</code>).</li>\n<li><strong>Leere Wertlisten:</strong> Das Attribut <code>vf</code> in <code>SwGenericAxisParam</code> erlaubt eine leere Wertebelegung (<code>[0..*]</code>), behält jedoch die Ordnungseigenschaft (<code>{ordered}</code>).</li>\n<li><strong>Variantenbildung:</strong> Die Parameterwerte <code>vf</code> unterliegen dem Variantenmanagement (<code>«atpVariation»</code>).</li>\n</ul>"}, {"id": "FIG-b044f8808a119fac", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR M2-Metamodells aus <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells für anwenderspezifische bzw. generische Stützstellenachsen (<code>SwAxisGeneric</code>) innerhalb der Kalibrier- und Messdatenmodellierung (<code>SwDataDefProps</code>). Es dient der Abbildung von Kennlinien- und Kennfeld-Achsen (Curves/Maps), deren Interpolationslogik oder Speicherorganisation von standardisierten AUTOSAR-Achstypen (z. B. <code>STD_AXIS</code>, <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>RES_AXIS</code>) abweicht und proprietäre Parameter für Kalibriertools (ASAM MCD-2 MC / A2L) sowie anwendungsspezifische Interpolationsroutinen benötigt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> (Klasse):</strong></li>\n<li>Konkrete Verwendung/Instanz einer generischen Achse.</li>\n<li><strong><code>SwGenericAxisParam</code> (Klasse):</strong></li>\n<li>Konkrete Belegung eines generischen Achsparameters.</li>\n<li>Attribut: <code>vf: Numerical [0..*] {ordered}</code> – Geordnete Sequenz von beliebig vielen (auch null) numerischen Werten; annotiert mit <code>«atpVariation»</code>.</li>\n<li><strong><code>SwAxisType</code> (Klasse, spezialisiert <code>ARElement</code>):</strong></li>\n<li>Top-Level-Modellelement (<code>ARElement</code>), definiert die Schablone für generische Achsen.</li>\n<li><strong><code>SwGenericAxisParamType</code> (Klasse, spezialisiert <code>Identifiable</code>):</strong></li>\n<li>Formale Parameterdefinition innerhalb eines <code>SwAxisType</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> $\\rightarrow$ <code>SwAxisType</code>:</strong> Unidirektionale Referenz <code>+swAxisType</code> mit Multiplizität <code>0..1</code> (optional).</li>\n<li><strong><code>SwAxisGeneric</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParam</code>:</strong> Komposition <code>+swGenericAxisParam</code> mit Multiplizität <code>0..*</code>.</li>\n<li><strong><code>SwGenericAxisParam</code> $\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Unidirektionale Assoziation <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..1</code> (optional).</li>\n<li><strong><code>SwAxisType</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Komposition <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Typ-Instanz-Muster (Design-Time / Modellierung):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Typdeklaration:</em> Definition eines wiederverwendbaren <code>SwAxisType</code> im Modell inklusive dessen formaler Parameter (<code>SwGenericAxisParamType</code>).</li>\n<li><em>Instanziierung:</em> Bei Deklaration einer Kennlinie/eines Kennfelds wird ein <code>SwAxisGeneric</code> zugewiesen, der auf den <code>SwAxisType</code> verweist.</li>\n<li><em>Parametrierung:</em> Für jeden geforderten <code>SwGenericAxisParamType</code> instanziiert <code>SwAxisGeneric</code> ein <code>SwGenericAxisParam</code> mit dem konkreten Wert <code>vf</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Build- & Toolchain-Abhängigkeit:</strong></li>\n<li>Keine direkte Laufzeit-Zustandsmaschine; statische Struktur dient Generatoren (RTE-Generator, A2L-Exportfilter).</li>\n<li>Evaluierung der <code>«atpVariation»</code>-Bedingungen während des System-/ECU-Extracts oder zur Post-Build-Ladephase.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Optionale Typisierung:</strong> Die Referenz <code>+swAxisType</code> von <code>SwAxisGeneric</code> ist optional (<code>0..1</code>). Ebenso ist die Typzuordnung <code>+swGenericAxisParamType</code> an <code>SwGenericAxisParam</code> optional (<code>0..1</code>).</li>\n<li><strong>Leere Wertlisten:</strong> Das Attribut <code>vf</code> in <code>SwGenericAxisParam</code> erlaubt eine leere Wertebelegung (<code>[0..*]</code>), behält jedoch die Ordnungseigenschaft (<code>{ordered}</code>).</li>\n<li><strong>Variantenbildung:</strong> Die Parameterwerte <code>vf</code> unterliegen dem Variantenmanagement (<code>«atpVariation»</code>).</li>\n</ul>"}, {"id": "FIG-c0dac950280310f3", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt des AUTOSAR M2-Metamodells aus <code>AUTOSAR_TPS_SoftwareComponentTemplate</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Spezifikation des Metamodells für anwenderspezifische bzw. generische Stützstellenachsen (<code>SwAxisGeneric</code>) innerhalb der Kalibrier- und Messdatenmodellierung (<code>SwDataDefProps</code>). Es dient der Abbildung von Kennlinien- und Kennfeld-Achsen (Curves/Maps), deren Interpolationslogik oder Speicherorganisation von standardisierten AUTOSAR-Achstypen (z. B. <code>STD_AXIS</code>, <code>FIX_AXIS</code>, <code>COM_AXIS</code>, <code>RES_AXIS</code>) abweicht und proprietäre Parameter für Kalibriertools (ASAM MCD-2 MC / A2L) sowie anwendungsspezifische Interpolationsroutinen benötigt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Entitäten & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> (Klasse):</strong></li>\n<li>Konkrete Verwendung/Instanz einer generischen Achse.</li>\n<li><strong><code>SwGenericAxisParam</code> (Klasse):</strong></li>\n<li>Konkrete Belegung eines generischen Achsparameters.</li>\n<li>Attribut: <code>vf: Numerical [0..*] {ordered}</code> – Geordnete Sequenz von beliebig vielen (auch null) numerischen Werten; annotiert mit <code>«atpVariation»</code>.</li>\n<li><strong><code>SwAxisType</code> (Klasse, spezialisiert <code>ARElement</code>):</strong></li>\n<li>Top-Level-Modellelement (<code>ARElement</code>), definiert die Schablone für generische Achsen.</li>\n<li><strong><code>SwGenericAxisParamType</code> (Klasse, spezialisiert <code>Identifiable</code>):</strong></li>\n<li>Formale Parameterdefinition innerhalb eines <code>SwAxisType</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Beziehungen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code> $\\rightarrow$ <code>SwAxisType</code>:</strong> Unidirektionale Referenz <code>+swAxisType</code> mit Multiplizität <code>0..1</code> (optional).</li>\n<li><strong><code>SwAxisGeneric</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParam</code>:</strong> Komposition <code>+swGenericAxisParam</code> mit Multiplizität <code>0..*</code>.</li>\n<li><strong><code>SwGenericAxisParam</code> $\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Unidirektionale Assoziation <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..1</code> (optional).</li>\n<li><strong><code>SwAxisType</code> $\\diamond\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Komposition <code>+swGenericAxisParamType</code> mit Multiplizität <code>0..*</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Typ-Instanz-Muster (Design-Time / Modellierung):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Typdeklaration:</em> Definition eines wiederverwendbaren <code>SwAxisType</code> im Modell inklusive dessen formaler Parameter (<code>SwGenericAxisParamType</code>).</li>\n<li><em>Instanziierung:</em> Bei Deklaration einer Kennlinie/eines Kennfelds wird ein <code>SwAxisGeneric</code> zugewiesen, der auf den <code>SwAxisType</code> verweist.</li>\n<li><em>Parametrierung:</em> Für jeden geforderten <code>SwGenericAxisParamType</code> instanziiert <code>SwAxisGeneric</code> ein <code>SwGenericAxisParam</code> mit dem konkreten Wert <code>vf</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Build- & Toolchain-Abhängigkeit:</strong></li>\n<li>Keine direkte Laufzeit-Zustandsmaschine; statische Struktur dient Generatoren (RTE-Generator, A2L-Exportfilter).</li>\n<li>Evaluierung der <code>«atpVariation»</code>-Bedingungen während des System-/ECU-Extracts oder zur Post-Build-Ladephase.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Optionale Typisierung:</strong> Die Referenz <code>+swAxisType</code> von <code>SwAxisGeneric</code> ist optional (<code>0..1</code>). Ebenso ist die Typzuordnung <code>+swGenericAxisParamType</code> an <code>SwGenericAxisParam</code> optional (<code>0..1</code>).</li>\n<li><strong>Leere Wertlisten:</strong> Das Attribut <code>vf</code> in <code>SwGenericAxisParam</code> erlaubt eine leere Wertebelegung (<code>[0..*]</code>), behält jedoch die Ordnungseigenschaft (<code>{ordered}</code>).</li>\n<li><strong>Variantenbildung:</strong> Die Parameterwerte <code>vf</code> unterliegen dem Variantenmanagement (<code>«atpVariation»</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-7a402db46c0b56f7", "to": "FIG-7f8c03f6dcbba163", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code>:</strong> Attribut <code>swNumberOfAxisPoints</code> mit Kardinalität <code>[0..1]</code> explizit spezifiziert.</li>\n<li><strong><code>SwGenericAxisParam</code>:</strong> Attribut <code>vf: Numerical</code> erhält Kardinalität <code>[1..*]</code>.</li>\n<li><strong>Layout:</strong> Diagrammanordnung von horizontaler Staffelung zu vertikal kompakter 2x2-Blockanordnung umgestellt.</li>\n</ul>"}, {"from": "FIG-7f8c03f6dcbba163", "to": "FIG-97909f64548ac947", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong><code>SwAxisGeneric</code>:</strong> Attribut <code>swNumberOfAxisPoints</code> entfernt (Klasse besitzt keine eigenen Attribute mehr im Diagramm).</li>\n</ul>"}, {"from": "FIG-97909f64548ac947", "to": "FIG-4403f342ca4feff4", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong><code>SwGenericAxisParam</code>:</strong> Eigenschafts-Modifier <code>{ordered}</code> für Attribut <code>vf: Numerical [1..*]</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-4403f342ca4feff4", "to": "FIG-3e4e3f41a2f3d6c2", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3e4e3f41a2f3d6c2", "to": "FIG-f5d15fe9842cd792", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong><code>SwGenericAxisParam</code>:</strong> Multiplizität des Attributs <code>vf</code> von <code>[1..<em>]</code> auf <code>[0..</em>]</code> gelockert.</li>\n<li><strong><code>SwAxisGeneric</code> $\\rightarrow$ <code>SwAxisType</code>:</strong> Multiplizität der Assoziationsrolle <code>+swAxisType</code> von <code>1</code> auf optional <code>0..1</code> geändert.</li>\n<li><strong><code>SwGenericAxisParam</code> $\\rightarrow$ <code>SwGenericAxisParamType</code>:</strong> Multiplizität der Assoziationsrolle <code>+swGenericAxisParamType</code> von <code>1</code> auf optional <code>0..1</code> geändert.</li>\n</ul>"}, {"from": "FIG-f5d15fe9842cd792", "to": "FIG-95424b0e01017484", "fr": "R20-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Layout:</strong> Diagrammanordnung von vertikalem Blocklayout (2x2) auf breite dreispaltige horizontale Anordnung umgestellt.</li>\n</ul>"}, {"from": "FIG-95424b0e01017484", "to": "FIG-b044f8808a119fac", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b044f8808a119fac", "to": "FIG-c0dac950280310f3", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
